<script setup lang="ts">
import {ref,onBeforeUnmount} from 'vue'
type Toast={id:number,kind:string,message:string,auto:boolean}
const items=ref<Toast[]>([]),autohide=ref(false),addButton=ref<HTMLButtonElement>(),timers=new Map<number,ReturnType<typeof setTimeout>>()
let nextId=0
function pause(id:number){clearTimeout(timers.get(id));timers.delete(id)}
function resume(item:Toast,event?:MouseEvent|FocusEvent){const node=event?.currentTarget as HTMLElement|undefined;if(node&&(event?.type==='mouseleave'?node.contains(document.activeElement):node.matches(':hover')||node.contains((event as FocusEvent).relatedTarget as Node)))return;pause(item.id);if(item.auto)timers.set(item.id,setTimeout(()=>dismiss(item.id),6000))}
function add(kind:string){const item={id:++nextId,kind,message:kind==='Success'?'Sample changes saved locally.':kind==='Warning'?'Sample review is still needed.':'Sample background check finished.',auto:autohide.value};items.value.push(item);resume(item)}
function dismiss(id:number,event?:Event){const focused=!!event&&(event.currentTarget as HTMLElement).contains(document.activeElement);pause(id);items.value=items.value.filter(x=>x.id!==id);if(focused)addButton.value?.focus()}
function clear(){timers.forEach(clearTimeout);timers.clear();items.value=[]}
onBeforeUnmount(clear)
</script>
<template><section class="toast-usage" aria-label="Toast usage demonstration"><p>Fictitious local feedback. Nothing is saved to a server.</p><label class="auto"><input v-model="autohide" type="checkbox"> Auto-hide new toasts after 6 seconds</label><div class="actions"><button ref="addButton" type="button" @click="add('Success')">Add success toast</button><button type="button" @click="add('Info')">Add info toast</button><button type="button" @click="add('Warning')">Add warning toast</button><button type="button" @click="clear">Clear sample stack</button></div><div class="stack" aria-label="Local toast stack"><article v-for="item in items" :key="item.id" class="toast" @mouseenter="pause(item.id)" @mouseleave="resume(item,$event)" @focusin="pause(item.id)" @focusout="resume(item,$event)"><div role="status" aria-atomic="true"><strong>{{item.kind}} · #{{item.id}}</strong><p>{{item.message}}</p><small>{{item.auto?'Auto-hide enabled; hover or focus pauses it.':'Stays until dismissed.'}}</small></div><button type="button" :aria-label="`Dismiss ${item.kind.toLowerCase()} toast ${item.id}`" @click="dismiss(item.id,$event)">×</button></article><p v-if="!items.length">No sample toasts. Add one above.</p></div></section></template>
<style scoped>
.toast-usage{padding:20px;margin:20px 0;border:1px solid var(--vp-c-divider);border-radius:12px}.actions{display:flex;flex-wrap:wrap;gap:12px;margin:20px 0}.auto{display:flex;gap:10px;align-items:center}button{min-height:44px;padding:8px 12px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg-soft)}.stack{display:flex;flex-direction:column;gap:12px;max-height:420px;overflow:auto;padding:4px}.toast{display:flex;justify-content:space-between;align-items:start;gap:12px;min-width:0;padding:16px;border:1px solid var(--vp-c-divider);border-left:4px solid var(--vp-c-brand-1);border-radius:8px;background:var(--vp-c-bg-soft);animation:toast-enter 160ms ease-out}.toast div{min-width:0;overflow-wrap:anywhere}.toast p{margin:6px 0}.toast small{display:block}.toast button{flex-shrink:0}:focus-visible{outline:3px solid var(--vp-c-brand-1);outline-offset:2px}@keyframes toast-enter{from{opacity:.3;translate:0 5px}to{opacity:1;translate:0 0}}@media(prefers-reduced-motion:reduce){.toast{animation:none}}
</style>
